func importLDBdata(ctx *cli.Context) error {
	start := 0
	switch ctx.NArg() {
	case 1:
		break
	case 2:
		s, err := strconv.Atoi(ctx.Args().Get(1))
		if err != nil {
			return fmt.Errorf("second arg must be an integer: %v", err)
		}
		start = s
	default:
		return fmt.Errorf("required arguments: %v", ctx.Command.ArgsUsage)
	}
	var (
		fName     = ctx.Args().Get(0)
		stack, _  = makeConfigNode(ctx)
		interrupt = make(chan os.Signal, 1)
		stop      = make(chan struct{})
	)
	defer stack.Close()
	signal.Notify(interrupt, syscall.SIGINT, syscall.SIGTERM)
	defer signal.Stop(interrupt)
	defer close(interrupt)
	go func() {
		if _, ok := <-interrupt; ok {
			log.Info("Interrupted during ldb import, stopping at next batch")
		}
		close(stop)
	}()
	db := utils.MakeChainDatabase(ctx, stack, false)
	defer db.Close()
	return utils.ImportLDBData(db, fName, int64(start), stop)
}

func MakeAddress(ks *keystore.KeyStore, account string) (accounts.Account, error) {
	// If the specified account is a valid address, return it
	if common.IsHexAddress(account) {
		return accounts.Account{Address: common.HexToAddress(account)}, nil
	}
	// Otherwise try to interpret the account as a keystore index
	index, err := strconv.Atoi(account)
	if err != nil || index < 0 {
		return accounts.Account{}, fmt.Errorf("invalid account address or index %q", account)
	}
	log.Warn("-------------------------------------------------------------------")
	log.Warn("Referring to accounts by order in the keystore folder is dangerous!")
	log.Warn("This functionality is deprecated and will be removed in the future!")
	log.Warn("Please use explicit addresses! (can search via `geth account list`)")
	log.Warn("-------------------------------------------------------------------")

	accs := ks.Accounts()
	if len(accs) <= index {
		return accounts.Account{}, fmt.Errorf("index %d higher than number of accounts %d", index, len(accs))
	}
	return accs[index], nil
}

func setRequiredBlocks(ctx *cli.Context, cfg *ethconfig.Config) {
	requiredBlocks := ctx.String(EthRequiredBlocksFlag.Name)
	if requiredBlocks == "" {
		if ctx.IsSet(LegacyWhitelistFlag.Name) {
			log.Warn("The flag --whitelist is deprecated and will be removed, please use --eth.requiredblocks")
			requiredBlocks = ctx.String(LegacyWhitelistFlag.Name)
		} else {
			return
		}
	}
	cfg.RequiredBlocks = make(map[uint64]common.Hash)
	for _, entry := range strings.Split(requiredBlocks, ",") {
		parts := strings.Split(entry, "=")
		if len(parts) != 2 {
			Fatalf("Invalid required block entry: %s", entry)
		}
		number, err := strconv.ParseUint(parts[0], 0, 64)
		if err != nil {
			Fatalf("Invalid required block number %s: %v", parts[0], err)
		}
		var hash common.Hash
		if err = hash.UnmarshalText([]byte(parts[1])); err != nil {
			Fatalf("Invalid required block hash %s: %v", parts[1], err)
		}
		cfg.RequiredBlocks[number] = hash
	}
}

func DecodeUint64(input string) (uint64, error) {
	raw, err := checkNumber(input)
	if err != nil {
		return 0, err
	}
	dec, err := strconv.ParseUint(raw, 16, 64)
	if err != nil {
		err = mapError(err)
	}
	return dec, err
}

func ParseUint64(s string) (uint64, bool) {
	if s == "" {
		return 0, true
	}
	if len(s) >= 2 && (s[:2] == "0x" || s[:2] == "0X") {
		v, err := strconv.ParseUint(s[2:], 16, 64)
		return v, err == nil
	}
	v, err := strconv.ParseUint(s, 10, 64)
	return v, err == nil
}

func (d *Decimal) UnmarshalJSON(input []byte) error {
	if !isString(input) {
		return &json.UnmarshalTypeError{Value: "non-string", Type: reflect.TypeOf(uint64(0))}
	}
	if i, err := strconv.ParseInt(string(input[1:len(input)-1]), 10, 64); err == nil {
		*d = Decimal(i)
		return nil
	} else {
		return err
	}
}

func Fuzz(data []byte) int {
	if len(data) < 32 {
		return -1
	}
	tmpFile, err := os.CreateTemp("", "")
	if err != nil {
		panic(err)
	}
	defer os.Remove(tmpFile.Name())
	defer tmpFile.Close()

	testSecKey, testPubKey := createKeyPair()
	// Create message
	tmpFile.Write(data)
	if err = tmpFile.Close(); err != nil {
		panic(err)
	}
	// Fuzz comments
	var untrustedComment string
	var trustedComment string
	f := fuzz.NewFromGoFuzz(data)
	f.Fuzz(&untrustedComment)
	f.Fuzz(&trustedComment)
	fmt.Printf("untrusted: %v\n", untrustedComment)
	fmt.Printf("trusted: %v\n", trustedComment)

	err = SignifySignFile(tmpFile.Name(), tmpFile.Name()+".sig", testSecKey, untrustedComment, trustedComment)
	if err != nil {
		panic(err)
	}
	defer os.Remove(tmpFile.Name() + ".sig")

	signify := "signify"
	path := os.Getenv("SIGNIFY")
	if path != "" {
		signify = path
	}

	_, err := exec.LookPath(signify)
	if err != nil {
		panic(err)
	}

	// Write the public key into the file to pass it as
	// an argument to signify-openbsd
	pubKeyFile, err := os.CreateTemp("", "")
	if err != nil {
		panic(err)
	}
	defer os.Remove(pubKeyFile.Name())
	defer pubKeyFile.Close()
	pubKeyFile.WriteString("untrusted comment: signify public key\n")
	pubKeyFile.WriteString(testPubKey)
	pubKeyFile.WriteString("\n")

	cmd := exec.Command(signify, "-V", "-p", pubKeyFile.Name(), "-x", tmpFile.Name()+".sig", "-m", tmpFile.Name())
	if output, err := cmd.CombinedOutput(); err != nil {
		panic(fmt.Sprintf("could not verify the file: %v, output: \n%s", err, output))
	}

	// Verify the signature using a golang library
	sig, err := minisign.NewSignatureFromFile(tmpFile.Name() + ".sig")
	if err != nil {
		panic(err)
	}

	pKey, err := minisign.NewPublicKey(testPubKey)
	if err != nil {
		panic(err)
	}

	valid, err := pKey.VerifyFromFile(tmpFile.Name(), sig)
	if err != nil {
		panic(err)
	}
	if !valid {
		panic("invalid signature")
	}
	return 1
}

func createKeyPair() (string, string) {
	// Create key and put it in correct format
	tmpKey, err := os.CreateTemp("", "")
	if err != nil {
		panic(err)
	}
	defer os.Remove(tmpKey.Name())
	defer os.Remove(tmpKey.Name() + ".pub")
	defer os.Remove(tmpKey.Name() + ".sec")
	cmd := exec.Command("signify", "-G", "-n", "-p", tmpKey.Name()+".pub", "-s", tmpKey.Name()+".sec")
	if output, err := cmd.CombinedOutput(); err != nil {
		panic(fmt.Sprintf("could not verify the file: %v, output: \n%s", err, output))
	}
	secKey, err := getKey(tmpKey.Name() + ".sec")
	if err != nil {
		panic(err)
	}
	pubKey, err := getKey(tmpKey.Name() + ".pub")
	if err != nil {
		panic(err)
	}
	return secKey, pubKey
}

func (b *Long) UnmarshalGraphQL(input interface{}) error {
	var err error
	switch input := input.(type) {
	case string:
		// uncomment to support hex values
		if strings.HasPrefix(input, "0x") {
			// apply leniency and support hex representations of longs.
			value, err := hexutil.DecodeUint64(input)
			*b = Long(value)
			return err
		} else {
			value, err := strconv.ParseInt(input, 10, 64)
			*b = Long(value)
			return err
		}
	case int32:
		*b = Long(input)
	case int64:
		*b = Long(input)
	case float64:
		*b = Long(input)
	default:
		err = fmt.Errorf("unexpected type %T for Long", input)
	}
	return err
}

func getDate(commit string) string {
	if commit == "" {
		return ""
	}
	out := RunGit("show", "-s", "--format=%ct", commit)
	if out == "" {
		return ""
	}
	date, err := strconv.ParseInt(strings.TrimSpace(out), 10, 64)
	if err != nil {
		panic(fmt.Sprintf("failed to parse git commit date: %v", err))
	}
	return time.Unix(date, 0).Format("20060102")
}

func (g *GoToolchain) goTool(command string, args ...string) *exec.Cmd {
	if g.Root == "" {
		g.Root = runtime.GOROOT()
	}
	tool := exec.Command(filepath.Join(g.Root, "bin", "go"), command) // nolint: gosec
	tool.Args = append(tool.Args, args...)
	tool.Env = append(tool.Env, "GOROOT="+g.Root)

	// Forward environment variables to the tool, but skip compiler target settings.
	// TODO: what about GOARM?
	skip := map[string]struct{}{"GOROOT": {}, "GOARCH": {}, "GOOS": {}, "GOBIN": {}, "CC": {}}
	for _, e := range os.Environ() {
		if i := strings.IndexByte(e, '='); i >= 0 {
			if _, ok := skip[e[:i]]; ok {
				continue
			}
		}
		tool.Env = append(tool.Env, e)
	}
	return tool
}

func MustRunCommand(cmd string, args ...string) {
	MustRun(exec.Command(cmd, args...))
}

func MustRunCommandWithOutput(cmd string, args ...string) {
	interval := time.NewTicker(time.Minute)
	done := make(chan struct{})
	defer interval.Stop()
	defer close(done)
	go func() {
		for {
			select {
			case <-interval.C:
				fmt.Printf("Waiting for command %q\n", cmd)
			case <-done:
				return
			}
		}
	}()
	MustRun(exec.Command(cmd, args...))
}

func RunGit(args ...string) string {
	cmd := exec.Command("git", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		if e, ok := err.(*exec.Error); ok && e.Err == exec.ErrNotFound {
			if !warnedAboutGit {
				log.Println("Warning: can't find 'git' in PATH")
				warnedAboutGit = true
			}
			return ""
		}
		log.Fatal(strings.Join(cmd.Args, " "), ": ", err, "\n", stderr.String())
	}
	return strings.TrimSpace(stdout.String())
}

func UploadSFTP(identityFile, host, dir string, files []string) error {
	sftp := exec.Command("sftp")
	sftp.Stderr = os.Stderr
	if identityFile != "" {
		sftp.Args = append(sftp.Args, "-i", identityFile)
	}
	sftp.Args = append(sftp.Args, host)
	fmt.Println(">>>", printArgs(sftp.Args))
	if *DryRunFlag {
		return nil
	}

	stdin, err := sftp.StdinPipe()
	if err != nil {
		return fmt.Errorf("can't create stdin pipe for sftp: %v", err)
	}
	stdout, err := sftp.StdoutPipe()
	if err != nil {
		return fmt.Errorf("can't create stdout pipe for sftp: %v", err)
	}
	if err := sftp.Start(); err != nil {
		return err
	}
	in := io.MultiWriter(stdin, os.Stdout)
	for _, f := range files {
		fmt.Fprintln(in, "put", f, path.Join(dir, filepath.Base(f)))
	}
	fmt.Fprintln(in, "exit")
	// Some issue with the PPA sftp server makes it so the server does not
	// respond properly to a 'bye', 'exit' or 'quit' from the client.
	// To work around that, we check the output, and when we see the client
	// exit command, we do a hard exit.
	// See
	// https://github.com/kolban-google/sftp-gcs/issues/23
	// https://github.com/mscdex/ssh2/pull/1111
	aborted := false
	go func() {
		scanner := bufio.NewScanner(stdout)
		for scanner.Scan() {
			txt := scanner.Text()
			fmt.Println(txt)
			if txt == "sftp> exit" {
				// Give it .5 seconds to exit (server might be fixed), then
				// hard kill it from the outside
				time.Sleep(500 * time.Millisecond)
				aborted = true
				sftp.Process.Kill()
			}
		}
	}()
	stdin.Close()
	err = sftp.Wait()
	if aborted {
		return nil
	}
	return err
}

func ReadDir(dir, network string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("error reading directory %s: %w", dir, err)
	}
	var (
		next = uint64(0)
		eras []string
	)
	for _, entry := range entries {
		if path.Ext(entry.Name()) != ".era1" {
			continue
		}
		parts := strings.Split(entry.Name(), "-")
		if len(parts) != 3 || parts[0] != network {
			// invalid era1 filename, skip
			continue
		}
		if epoch, err := strconv.ParseUint(parts[1], 10, 64); err != nil {
			return nil, fmt.Errorf("malformed era1 filename: %s", entry.Name())
		} else if epoch != next {
			return nil, fmt.Errorf("missing epoch %d", next)
		}
		next += 1
		eras = append(eras, entry.Name())
	}
	return eras, nil
}

func (h *GlogHandler) Vmodule(ruleset string) error {
	var filter []pattern
	for _, rule := range strings.Split(ruleset, ",") {
		// Empty strings such as from a trailing comma can be ignored
		if len(rule) == 0 {
			continue
		}
		// Ensure we have a pattern = level filter rule
		parts := strings.Split(rule, "=")
		if len(parts) != 2 {
			return errVmoduleSyntax
		}
		parts[0] = strings.TrimSpace(parts[0])
		parts[1] = strings.TrimSpace(parts[1])
		if len(parts[0]) == 0 || len(parts[1]) == 0 {
			return errVmoduleSyntax
		}
		// Parse the level and if correct, assemble the filter rule
		l, err := strconv.Atoi(parts[1])
		if err != nil {
			return errVmoduleSyntax
		}
		level := FromLegacyLevel(l)

		if level == LevelCrit {
			continue // Ignore. It's harmless but no point in paying the overhead.
		}
		// Compile the rule pattern into a regular expression
		matcher := ".*"
		for _, comp := range strings.Split(parts[0], "/") {
			if comp == "*" {
				matcher += "(/.*)?"
			} else if comp != "" {
				matcher += "/" + regexp.QuoteMeta(comp)
			}
		}
		if !strings.HasSuffix(parts[0], ".go") {
			matcher += "/[^/]+\\.go"
		}
		matcher = matcher + "$"

		re, _ := regexp.Compile(matcher)
		filter = append(filter, pattern{re, level})
	}
	// Swap out the vmodule pattern for the new filter system
	h.lock.Lock()
	defer h.lock.Unlock()

	h.patterns = filter
	h.siteCache = make(map[uintptr]slog.Level)
	h.override.Store(len(filter) != 0)

	return nil
}

func ReadDiskStats(stats *DiskStats) error {
	// Open the process disk IO counter file
	inf, err := os.Open(fmt.Sprintf("/proc/%d/io", os.Getpid()))
	if err != nil {
		return err
	}
	defer inf.Close()
	in := bufio.NewReader(inf)

	// Iterate over the IO counter, and extract what we need
	for {
		// Read the next line and split to key and value
		line, err := in.ReadString('\n')
		if err != nil {
			if err == io.EOF {
				return nil
			}
			return err
		}
		parts := strings.Split(line, ":")
		if len(parts) != 2 {
			continue
		}
		key := strings.TrimSpace(parts[0])
		value, err := strconv.ParseInt(strings.TrimSpace(parts[1]), 10, 64)
		if err != nil {
			return err
		}

		// Update the counter based on the key
		switch key {
		case "syscr":
			stats.ReadCount = value
		case "syscw":
			stats.WriteCount = value
		case "rchar":
			stats.ReadBytes = value
		case "wchar":
			stats.WriteBytes = value
		}
	}
}

func (w *gzipResponseWriter) init() {
	if w.inited {
		return
	}
	w.inited = true

	hdr := w.resp.Header()
	length := hdr.Get("content-length")
	if len(length) > 0 {
		if n, err := strconv.ParseUint(length, 10, 64); err != nil {
			w.hasLength = true
			w.contentLength = n
		}
	}

	// Setting Transfer-Encoding to "identity" explicitly disables compression. net/http
	// also recognizes this header value and uses it to disable "chunked" transfer
	// encoding, trimming the header from the response. This means downstream handlers can
	// set this without harm, even if they aren't wrapped by newGzipHandler.
	//
	// In go-ethereum, we use this signal to disable compression for certain error
	// responses which are flushed out close to the write deadline of the response. For
	// these cases, we want to avoid chunked transfer encoding and compression because
	// they require additional output that may not get written in time.
	passthrough := hdr.Get("transfer-encoding") == "identity"
	if !passthrough {
		w.gz = gzPool.Get().(*gzip.Writer)
		w.gz.Reset(w.resp)
		hdr.Del("content-length")
		hdr.Set("content-encoding", "gzip")
	}
}

func predictAddr(t *netutil.IPTracker) (net.IP, uint16) {
	ep := t.PredictEndpoint()
	if ep == "" {
		return nil, 0
	}
	ipString, portString, _ := net.SplitHostPort(ep)
	ip := net.ParseIP(ipString)
	port, err := strconv.ParseUint(portString, 10, 16)
	if err != nil {
		return nil, 0
	}
	return ip, uint16(port)
}

func parseComplete(rawurl string) (*Node, error) {
	var (
		id               *ecdsa.PublicKey
		tcpPort, udpPort uint64
	)
	u, err := url.Parse(rawurl)
	if err != nil {
		return nil, err
	}
	if u.Scheme != "enode" {
		return nil, errors.New("invalid URL scheme, want \"enode\"")
	}
	// Parse the Node ID from the user portion.
	if u.User == nil {
		return nil, errors.New("does not contain node ID")
	}
	if id, err = parsePubkey(u.User.String()); err != nil {
		return nil, fmt.Errorf("invalid public key (%v)", err)
	}
	// Parse the IP address.
	ip := net.ParseIP(u.Hostname())
	if ip == nil {
		ips, err := lookupIPFunc(u.Hostname())
		if err != nil {
			return nil, err
		}
		ip = ips[0]
	}
	// Ensure the IP is 4 bytes long for IPv4 addresses.
	if ipv4 := ip.To4(); ipv4 != nil {
		ip = ipv4
	}
	// Parse the port numbers.
	if tcpPort, err = strconv.ParseUint(u.Port(), 10, 16); err != nil {
		return nil, errors.New("invalid port")
	}
	udpPort = tcpPort
	qv := u.Query()
	if qv.Get("discport") != "" {
		udpPort, err = strconv.ParseUint(qv.Get("discport"), 10, 16)
		if err != nil {
			return nil, errors.New("invalid discport in query")
		}
	}
	return NewV4(id, ip, int(tcpPort), int(udpPort)), nil
}

func assignTCPPort() (uint16, error) {
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		return 0, err
	}
	l.Close()
	_, port, err := net.SplitHostPort(l.Addr().String())
	if err != nil {
		return 0, err
	}
	p, err := strconv.ParseUint(port, 10, 16)
	if err != nil {
		return 0, err
	}
	return uint16(p), nil
}

func (s *Server) StartMocker(w http.ResponseWriter, req *http.Request) {
	s.mockerMtx.Lock()
	defer s.mockerMtx.Unlock()
	if s.mockerStop != nil {
		http.Error(w, "mocker already running", http.StatusInternalServerError)
		return
	}
	mockerType := req.FormValue("mocker-type")
	mockerFn := LookupMocker(mockerType)
	if mockerFn == nil {
		http.Error(w, fmt.Sprintf("unknown mocker type %q", html.EscapeString(mockerType)), http.StatusBadRequest)
		return
	}
	nodeCount, err := strconv.Atoi(req.FormValue("node-count"))
	if err != nil {
		http.Error(w, "invalid node-count provided", http.StatusBadRequest)
		return
	}
	s.mockerStop = make(chan struct{})
	go mockerFn(s.network, s.mockerStop, nodeCount)

	w.WriteHeader(http.StatusOK)
}

func NewMsgFilters(filterParam string) (MsgFilters, error) {
	filters := make(MsgFilters)
	for _, filter := range strings.Split(filterParam, "-") {
		proto, codes, found := strings.Cut(filter, ":")
		if !found || proto == "" || codes == "" {
			return nil, fmt.Errorf("invalid message filter: %s", filter)
		}

		for _, code := range strings.Split(codes, ",") {
			if code == "*" || code == "-1" {
				filters[MsgFilter{Proto: proto, Code: -1}] = struct{}{}
				continue
			}
			n, err := strconv.ParseUint(code, 10, 64)
			if err != nil {
				return nil, fmt.Errorf("invalid message code: %s", code)
			}
			filters[MsgFilter{Proto: proto, Code: int64(n)}] = struct{}{}
		}
	}
	return filters, nil
}

func parseInteger(encType string, encValue interface{}) (*big.Int, error) {
	var (
		length int
		signed = strings.HasPrefix(encType, "int")
		b      *big.Int
	)
	if encType == "int" || encType == "uint" {
		length = 256
	} else {
		lengthStr := ""
		if strings.HasPrefix(encType, "uint") {
			lengthStr = strings.TrimPrefix(encType, "uint")
		} else {
			lengthStr = strings.TrimPrefix(encType, "int")
		}
		atoiSize, err := strconv.Atoi(lengthStr)
		if err != nil {
			return nil, fmt.Errorf("invalid size on integer: %v", lengthStr)
		}
		length = atoiSize
	}
	switch v := encValue.(type) {
	case *math.HexOrDecimal256:
		b = (*big.Int)(v)
	case *big.Int:
		b = v
	case string:
		var hexIntValue math.HexOrDecimal256
		if err := hexIntValue.UnmarshalText([]byte(v)); err != nil {
			return nil, err
		}
		b = (*big.Int)(&hexIntValue)
	case float64:
		// JSON parses non-strings as float64. Fail if we cannot
		// convert it losslessly
		if float64(int64(v)) == v {
			b = big.NewInt(int64(v))
		} else {
			return nil, fmt.Errorf("invalid float value %v for type %v", v, encType)
		}
	}
	if b == nil {
		return nil, fmt.Errorf("invalid integer value %v/%v for type %v", encValue, reflect.TypeOf(encValue), encType)
	}
	if b.BitLen() > length {
		return nil, fmt.Errorf("integer larger than '%v'", encType)
	}
	if !signed && b.Sign() == -1 {
		return nil, fmt.Errorf("invalid negative value for unsigned type %v", encType)
	}
	return b, nil
}

func (typedData *TypedData) EncodePrimitiveValue(encType string, encValue interface{}, depth int) ([]byte, error) {
	switch encType {
	case "address":
		retval := make([]byte, 32)
		switch val := encValue.(type) {
		case string:
			if common.IsHexAddress(val) {
				copy(retval[12:], common.HexToAddress(val).Bytes())
				return retval, nil
			}
		case []byte:
			if len(val) == 20 {
				copy(retval[12:], val)
				return retval, nil
			}
		case [20]byte:
			copy(retval[12:], val[:])
			return retval, nil
		}
		return nil, dataMismatchError(encType, encValue)
	case "bool":
		boolValue, ok := encValue.(bool)
		if !ok {
			return nil, dataMismatchError(encType, encValue)
		}
		if boolValue {
			return math.PaddedBigBytes(common.Big1, 32), nil
		}
		return math.PaddedBigBytes(common.Big0, 32), nil
	case "string":
		strVal, ok := encValue.(string)
		if !ok {
			return nil, dataMismatchError(encType, encValue)
		}
		return crypto.Keccak256([]byte(strVal)), nil
	case "bytes":
		bytesValue, ok := parseBytes(encValue)
		if !ok {
			return nil, dataMismatchError(encType, encValue)
		}
		return crypto.Keccak256(bytesValue), nil
	}
	if strings.HasPrefix(encType, "bytes") {
		lengthStr := strings.TrimPrefix(encType, "bytes")
		length, err := strconv.Atoi(lengthStr)
		if err != nil {
			return nil, fmt.Errorf("invalid size on bytes: %v", lengthStr)
		}
		if length < 0 || length > 32 {
			return nil, fmt.Errorf("invalid size on bytes: %d", length)
		}
		if byteValue, ok := parseBytes(encValue); !ok || len(byteValue) != length {
			return nil, dataMismatchError(encType, encValue)
		} else {
			// Right-pad the bits
			dst := make([]byte, 32)
			copy(dst, byteValue)
			return dst, nil
		}
	}
	if strings.HasPrefix(encType, "int") || strings.HasPrefix(encType, "uint") {
		b, err := parseInteger(encType, encValue)
		if err != nil {
			return nil, err
		}
		return math.U256Bytes(b), nil
	}
	return nil, fmt.Errorf("unrecognized type '%s'", encType)
}

func initializeCoinAdapter(coinAdapterAddress common.Address, param map[string]string, alloc *types.GenesisAlloc) ([]params.StateParam, error) {
	sp := make([]params.StateParam, 0)

	// SLOT_COIN_ADAPTER_MASTER_MINTER
	masterMinter, ok := param[COIN_ADAPTER_PARAM_MASTER_MINTER]
	if !ok || len(masterMinter) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_MASTER_MINTER)
	}
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_MASTER_MINTER),
		Value:   common.BytesToHash(common.HexToAddress(masterMinter).Bytes()),
	})

	// SLOT_COIN_ADAPTER_MINTERS, SLOT_COIN_ADAPTER_MINTER_ALLOWED
	if mintersStr, ok := param[COIN_ADAPTER_PARAM_MINTERS]; ok && len(mintersStr) > 0 {
		minters := splitAndTrim(mintersStr, ",")
		minterAllowedAmounts := make([]*big.Int, len(minters))
		if minterAllowedStr, ok := param[COIN_ADAPTER_PARAM_MINTER_ALLOWED]; ok && len(minterAllowedStr) > 0 {
			minterAllowed := splitAndTrim(minterAllowedStr, ",")
			if len(minters) != len(minterAllowed) {
				return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: the number of minters and minterAllowedAmounts must be the same")
			}
			for i, allowed := range minterAllowed {
				allowedAmount, ok := new(big.Int).SetString(allowed, 10)
				if !ok {
					return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: invalid minterAllowed, must be decimal")
				}
				minterAllowedAmounts[i] = allowedAmount
			}
		}
		mintersSlot := common.HexToHash(SLOT_COIN_ADAPTER_MINTERS)
		minterAllowedSlot := common.HexToHash(SLOT_COIN_ADAPTER_MINTER_ALLOWED)
		for i, minter := range minters {
			minterAddress := common.HexToAddress(minter)
			sp = append(sp, params.StateParam{
				Address: coinAdapterAddress,
				Key:     CalculateMappingSlot(mintersSlot, minterAddress),
				Value:   common.BytesToHash([]byte{1}), // == true
			})

			if minterAllowedAmounts[i] != nil {
				sp = append(sp, params.StateParam{
					Address: coinAdapterAddress,
					Key:     CalculateMappingSlot(minterAllowedSlot, minterAddress),
					Value:   common.BigToHash(minterAllowedAmounts[i]),
				})
			}
		}
	}

	// SLOT_COIN_ADAPTER_COIN_MANAGER
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_COIN_MANAGER),
		Value:   common.BytesToHash(params.NativeCoinManagerAddress.Bytes()),
	})

	// SLOT_COIN_ADAPTER_ACCOUNT_MANAGER
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_ACCOUNT_MANAGER),
		Value:   common.BytesToHash(params.AccountManagerAddress.Bytes()),
	})

	// SLOT_COIN_ADAPTER_NAME
	coinName, ok := param[COIN_ADAPTER_PARAM_NAME]
	if !ok || len(coinName) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_NAME)
	}
	for slot, value := range EncodeBytesToSlots(common.HexToHash(SLOT_COIN_ADAPTER_NAME), []byte(coinName)) {
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     slot,
			Value:   value,
		})
	}

	// SLOT_COIN_ADAPTER_SYMBOL
	symbol, ok := param[COIN_ADAPTER_PARAM_SYMBOL]
	if !ok || len(symbol) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_SYMBOL)
	}
	for slot, value := range EncodeBytesToSlots(common.HexToHash(SLOT_COIN_ADAPTER_SYMBOL), []byte(symbol)) {
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     slot,
			Value:   value,
		})
	}

	// SLOT_COIN_ADAPTER_DECIMALS
	decimalsStr, ok := param[COIN_ADAPTER_PARAM_DECIMALS]
	if !ok || len(decimalsStr) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_DECIMALS)
	}
	decimals, err := strconv.ParseUint(decimalsStr, 10, 8)
	if err != nil {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params.decimals`: %w", err)
	}
	sp = append(sp, params.StateParam{
		Address: coinAdapterAddress,
		Key:     common.HexToHash(SLOT_COIN_ADAPTER_DECIMALS),
		Value:   common.BytesToHash([]byte{uint8(decimals)}),
	})

	// SLOT_COIN_ADAPTER_CURRENCY
	currency, ok := param[COIN_ADAPTER_PARAM_CURRENCY]
	if !ok || len(currency) == 0 {
		return nil, fmt.Errorf("`systemContracts.nativeCoinAdapter.params`: missing parameter: %s", COIN_ADAPTER_PARAM_CURRENCY)
	}
	for slot, value := range EncodeBytesToSlots(common.HexToHash(SLOT_COIN_ADAPTER_CURRENCY), []byte(currency)) {
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     slot,
			Value:   value,
		})
	}

	// SLOT_COIN_ADAPTER_TOTAL_SUPPLY
	if alloc != nil {
		totalSupply := new(big.Int)
		for _, account := range *alloc {
			if account.Balance != nil {
				totalSupply.Add(totalSupply, account.Balance)
			}
		}
		sp = append(sp, params.StateParam{
			Address: coinAdapterAddress,
			Key:     common.HexToHash(SLOT_COIN_ADAPTER_TOTAL_SUPPLY),
			Value:   common.BigToHash(totalSupply),
		})
	}

	return sp, nil
}

func Compile(openzeppelinPath string, sourceFiles ...string) (compiledTy, error) {
	solcPath, err := solcdownloader.GetSolcBin(solcVersion)
	if err != nil {
		return nil, err
	}
	if openzeppelinPath == "" {
		openzeppelinPath = "../solidity/openzeppelin"
	}
	args := []string{
		"--combined-json", "bin,bin-runtime,srcmap,srcmap-runtime,abi,userdoc,devdoc,metadata,hashes",
		"--optimize",                // code optimizer switched on
		"--allow-paths", ".,./,../", //default to support relative path： ./  ../  .
		fmt.Sprintf("@openzeppelin/contracts/=%s/contracts/contracts/", openzeppelinPath),
		fmt.Sprintf("@openzeppelin/contracts-upgradeable/=%s/contracts-upgradeable/contracts/", openzeppelinPath),
		"--",
	}
	// ~/.solc-bin/solc-0.8.14
	cmd := exec.Command(solcPath, append(args, sourceFiles...)...)

	var stderr, stdout bytes.Buffer
	cmd.Stderr, cmd.Stdout = &stderr, &stdout
	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("solc: %v\n%s", err, stderr.Bytes())
	}

	// compiler version
	var compilerVersion = struct {
		Version string
	}{}

	if err := json.Unmarshal(stdout.Bytes(), &compilerVersion); err != nil {
		return nil, err
	} else if contracts, err := compiler.ParseCombinedJSON(stdout.Bytes(), "", "", compilerVersion.Version, strings.Join(args, " ")); err != nil {
		return nil, err
	} else {
		out := make(compiledTy)
		for name, v := range contracts {
			n := strings.Split(name, ":")[1]
			if _, ok := out[n]; ok {
				return nil, fmt.Errorf("duplicated contract name: %s", name)
			} else {
				out[n] = v
			}
		}
		return out, nil
	}
}

func GetSolcBin(version string) (string, error) {
	osName, ok := osMapping[runtime.GOOS]
	if !ok {
		return "", fmt.Errorf("unsupported OS: %s", runtime.GOOS)
	}
	arch := runtime.GOARCH
	// Handle ARM architecture
	if runtime.GOARCH == "arm64" {
		if osName == "macosx" {
			// Mac ARM → check Rosetta 2
			if err := exec.Command("pgrep", "oahd").Run(); err != nil {
				return "", fmt.Errorf("rosetta 2 is required to run amd64 solc binary on Apple Silicon")
			}
			arch = "amd64"
		} else {
			// ARM on non-Mac OS → unsupported
			return "", fmt.Errorf("unsupported architecture: ARM is not supported on %s", osName)
		}
	}

	// Home directory based path for storing solc binaries
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	dir := filepath.Join(home, solcBinDirName)
	if err := os.MkdirAll(dir, 0755); err != nil {
		return "", err
	}

	// Local binary file name
	binName := fmt.Sprintf("solc-%s", version)
	if osName == "windows" {
		binName += ".exe"
	}
	binPath := filepath.Join(dir, binName)

	// Return the path immediately if the binary already exists
	if _, err := os.Stat(binPath); err == nil {
		return binPath, nil
	}

	fmt.Printf("%s not found, downloading...\n", binName)

	// Windows versions below 0.7.2 are unsupported
	if osName == "windows" && versionCompare(version, "0.7.2") < 0 {
		return "", fmt.Errorf("unsupported version on Windows: %s. Please use >=0.7.2", version)
	}

	// Fetch list.json to find the build info
	listURL := fmt.Sprintf("%s/%s-%s/list.json", solcRepoURL, osName, arch)
	build, err := getBuild(listURL, version)
	if err != nil {
		return "", err
	}

	// Construct download URL using the build path
	downloadUrl := fmt.Sprintf("%s/%s-%s/%s", solcRepoURL, osName, arch, build.Path)
	if err := downloadSolc(binPath, downloadUrl); err != nil {
		return "", err
	}

	// Verify SHA256 checksum
	if ok, err := verifyChecksum(binPath, build.Sha256); err != nil {
		return "", err
	} else if !ok {
		os.Remove(binPath)
		return "", fmt.Errorf("downloaded file checksum mismatch")
	}

	// Set executable permission on macOS/Linux
	if osName != "windows" {
		if err := os.Chmod(binPath, 0755); err != nil {
			return "", err
		}
	}

	fmt.Println("Download complete:", binPath)
	return binPath, nil
}

func initializeBase(govBaseAddress common.Address, param map[string]string) ([]params.StateParam, error) {
	sp := make([]params.StateParam, 0)

	quorum := uint64(0)
	if quorumStr, ok := param[GOV_BASE_PARAM_QUORUM]; ok {
		var err error
		quorum, err = strconv.ParseUint(quorumStr, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("`systemContracts.govBase.params.quorum`: %w", err)
		}

		// Validate quorum is greater than 0
		if quorum == 0 {
			return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` must be greater than 0")
		}

		sp = append(sp,
			params.StateParam{
				Address: govBaseAddress,
				Key:     common.HexToHash(SLOT_GOV_BASE_quorum),
				Value:   common.BigToHash(big.NewInt(int64(quorum))),
			},
		)
	}

	if expiryStr, ok := param[GOV_BASE_PARAM_EXPIRY]; ok {
		expiry, err := strconv.ParseUint(expiryStr, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("`systemContracts.govBase.params.expiry`: %w", err)
		}
		sp = append(sp,
			params.StateParam{
				Address: govBaseAddress,
				Key:     common.HexToHash(SLOT_GOV_BASE_proposalExpiry),
				Value:   common.BigToHash(big.NewInt(int64(expiry))),
			},
		)
	}

	if membersStr, ok := param[GOV_BASE_PARAM_MEMBERS]; ok {
		memberAddresses := splitAndTrim(membersStr, ",")

		// Pre-validate and deduplicate members
		uniqueMembers := make([]common.Address, 0)
		seen := make(map[common.Address]struct{})
		for _, addrStr := range memberAddresses {
			member := common.HexToAddress(addrStr)

			// Validate zero address
			if member == (common.Address{}) {
				return nil, fmt.Errorf("`systemContracts.govBase.params.members` contains invalid zero address")
			}

			// Add to slice only if not seen before
			if _, exists := seen[member]; !exists {
				seen[member] = struct{}{}
				uniqueMembers = append(uniqueMembers, member)
			}
		}

		// Check quorum after deduplication
		if quorum > 0 && uint64(len(uniqueMembers)) < quorum {
			return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` (%d) must not be greater than unique member count (%d)", quorum, len(uniqueMembers))
		}

		// Enforce maximum member limit (matches Solidity MAX_MEMBER_INDEX)
		const MAX_MEMBERS = 255
		if len(uniqueMembers) > MAX_MEMBERS {
			return nil, fmt.Errorf("`systemContracts.govBase.params.members` count (%d) exceeds maximum allowed (%d)", len(uniqueMembers), MAX_MEMBERS)
		}

		// Quorum validation matching GovBase.sol logic
		// This ensures consistency between genesis initialization and smart contract behavior
		// Only validate if quorum is explicitly provided (quorum > 0)
		if quorum > 0 {
			memberCount := uint64(len(uniqueMembers))
			if memberCount == 1 {
				// Single member governance: quorum must be exactly 1
				// WARNING: Single-member governance is centralized and not recommended for production
				if quorum != 1 {
					return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` must be exactly 1 for single-member governance, got %d", quorum)
				}
			} else {
				// Multi-member governance: require at least 2 approvals (proposer + 1 reviewer)
				// This prevents any single member from executing proposals without peer review
				// Security: quorum=1 would allow single-member unilateral decisions
				if quorum < 2 {
					return nil, fmt.Errorf("`systemContracts.govBase.params.quorum` (%d) must be at least 2 for multi-member governance (member count: %d)", quorum, memberCount)
				}
			}
		}

		membersSlot := common.HexToHash(SLOT_GOV_BASE_members)
		versionedMemberListSlot := common.HexToHash(SLOT_GOV_BASE_versionedMemberList)
		versionSlot := common.HexToHash(SLOT_GOV_BASE_version)
		memberIndexByVersionSlot := common.HexToHash(SLOT_GOV_BASE_memberIndexByVersion)
		quorumByVersionSlot := common.HexToHash(SLOT_GOV_BASE_quorumByVersion)

		versionStr, ok2 := param[GOV_BASE_PARAM_MEMBER_VERSION]
		if !ok2 {
			return nil, fmt.Errorf("`systemContracts.govBase.params.memberVersion` is required when `systemContracts.govBase.params.members` is set")
		}
		versionInt, err := strconv.ParseUint(versionStr, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("`systemContracts.govBase.params.memberVersion`: %w", err)
		}
		version := new(big.Int).SetUint64(versionInt)

		// joinedAt is set to 0 for all initial members.
		// We do not use the current time in the genesis (configuration).
		// This is because it makes the genesis generation non-deterministic.
		memberData := Member{
			IsActive: true,
			JoinedAt: 0,
		}.ToHash()

		currentIdx := uint64(0)
		// Use uniqueMembers slice for iteration
		for _, member := range uniqueMembers {
			// Additional overflow check (defensive programming)
			if currentIdx >= MAX_MEMBERS {
				return nil, fmt.Errorf("member index overflow: currentIdx (%d) >= MAX_MEMBERS (%d)", currentIdx, MAX_MEMBERS)
			}
			sp = append(sp,
				// Set member active status and joinedAt timestamp
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateMappingSlot(membersSlot, member),
					Value:   memberData,
				},
				// Add member to versionedMemberList[version][currentIdx]
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateDynamicSlot(CalculateMappingSlot(versionedMemberListSlot, version), new(big.Int).SetUint64(currentIdx)),
					Value:   common.BytesToHash(member.Bytes()),
				},
				// Set memberIndexByVersion[version][member] = currentIdx + 1
				// Note: Index is 1-based (0 means not a member)
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateMappingSlot(CalculateMappingSlot(memberIndexByVersionSlot, version), member),
					Value:   common.BigToHash(new(big.Int).SetUint64(currentIdx + 1)),
				},
			)
			currentIdx++
		}

		if currentIdx > 0 {
			sp = append(sp,
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateMappingSlot(versionedMemberListSlot, version),
					Value:   common.BigToHash(new(big.Int).SetUint64(currentIdx)),
				},
			)
		}
		sp = append(sp,
			params.StateParam{
				Address: govBaseAddress,
				Key:     versionSlot,
				Value:   common.BigToHash(version),
			},
		)

		// Set quorumByVersion[version] = quorum
		// This creates a snapshot of the quorum value at this member version
		if quorum > 0 {
			sp = append(sp,
				params.StateParam{
					Address: govBaseAddress,
					Key:     CalculateMappingSlot(quorumByVersionSlot, version),
					Value:   common.BigToHash(new(big.Int).SetUint64(quorum)),
				},
			)
		}
	}

	// Initialize maxActiveProposalsPerMember (default: 3, range: 1-50)
	maxProposals := uint64(3) // Default value
	if maxProposalsStr, ok := param[GOV_BASE_PARAM_MAX_PROPOSALS]; ok {
		var err error
		maxProposals, err = strconv.ParseUint(maxProposalsStr, 10, 64)
		if err != nil {
			return nil, fmt.Errorf("`systemContracts.govBase.params.maxProposals`: %w", err)
		}

		// Validate range: 1 to 50 (inclusive)
		if maxProposals < 1 || maxProposals > 50 {
			return nil, fmt.Errorf("`systemContracts.govBase.params.maxProposals` must be between 1 and 50, got %d", maxProposals)
		}
	}

	sp = append(sp,
		params.StateParam{
			Address: govBaseAddress,
			Key:     common.HexToHash(SLOT_GOV_BASE_maxActiveProposalsPerMember),
			Value:   common.BigToHash(big.NewInt(int64(maxProposals))),
		},
	)

	return sp, nil
}

func GetChainConfig(forkString string) (baseConfig *params.ChainConfig, eips []int, err error) {
	var (
		splitForks            = strings.Split(forkString, "+")
		ok                    bool
		baseName, eipsStrings = splitForks[0], splitForks[1:]
	)
	if baseConfig, ok = Forks[baseName]; !ok {
		return nil, nil, UnsupportedForkError{baseName}
	}
	for _, eip := range eipsStrings {
		if eipNum, err := strconv.Atoi(eip); err != nil {
			return nil, nil, fmt.Errorf("syntax error, invalid eip number %v", eipNum)
		} else {
			if !vm.ValidEip(eipNum) {
				return nil, nil, fmt.Errorf("syntax error, invalid eip number %v", eipNum)
			}
			eips = append(eips, eipNum)
		}
	}
	return baseConfig, eips, nil
}
